/* ============================================================
 * 图标悬停发光动效 - v3.2
 * ============================================================ */

/* 所有交互图标统一 transition */
.interactable,
.fa-solid:not(#load-spinner),
.drawer-icon,
.menu_button .fa-solid,
#send_form .fa-solid,
#send_form a,
#top-settings-holder .fa-solid,
#top-bar .fa-solid {
