/* 角色头像悬停微光 */
.avatar img,
.character_select .avatar img {
  transition: filter 0.35s ease-out;
}

.avatar img:hover,
.character_select:hover .avatar img {
  filter: drop-shadow(0 0 6px rgba(184, 187, 38, 0.3));
}

/* ============================================================
 * 底部三按钮各自动效 - v3.3 新增
 * 汉堡菜单→抖动 / 魔杖→旋转 / 发送→书写摆动
 * ============================================================ */

/* --- 汉堡菜单：hover 抖动 --- */
#options_button .fa-solid,
#options_button {
  transition: filter 0.35s ease-out;
}

#options_button:hover .fa-solid,
#options_button:hover {
  animation: icon-shake 0.4s ease-in-out;
  filter: drop-shadow(0 0 4px rgba(184, 187, 38, 0.4));
}

@keyframes icon-shake {
  0%, 100% { transform: translateX(0) rotate(0); }
  20% { transform: translateX(-2px) rotate(-3deg); }
  40% { transform: translateX(2px) rotate(3deg); }
  60% { transform: translateX(-2px) rotate(-3deg); }
  80% { transform: translateX(2px) rotate(3deg); }
}

/* --- 魔杖：hover 旋转 --- */
#extensionsMenuButton {
  transition: filter 0.35s ease-out;
}

#extensionsMenuButton:hover {
  filter: drop-shadow(0 0 4px rgba(184, 187, 38, 0.4));
}

@keyframes icon-spin {
  0% { transform: rotate(0); }
  100% { transform: rotate(360deg); }
}

/* --- 发送按钮：hover 发光 + active 变暗（不用transform防撑边框） --- */
#send_but {
  transition: filter 0.35s ease-out, opacity 0.2s ease-out;
  filter: drop-shadow(0 0 2px rgba(184, 187, 38, 0.2));
}

#send_but:hover {
  filter: drop-shadow(0 0 8px rgba(184, 187, 38, 0.6));
}

#send_but:active {
  filter: drop-shadow(0 0 4px rgba(184, 187, 38, 0.3));
  opacity: 0.7;
}

