    background: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, transparent) !important;
    border-radius: 0 !important;
    z-index: 5 !important;
    pointer-events: auto !important;
    box-sizing: border-box !important;
  }
  #chat .mes .mesIDDisplay {
    border-radius: 4px 0 0 4px !important;
  }
  #chat .mes .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes .mes_timer:empty {
    display: none !important;
  }
  #chat .mes .tokenCounterDisplay:empty {
    display: none !important;
  }
  #chat .mes:has(.mes_timer:empty):has(.tokenCounterDisplay:empty) .mesIDDisplay {
    border-radius: 4px !important;
  }
  #chat .mes:has(.mes_timer:empty) .tokenCounterDisplay:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes:has(.tokenCounterDisplay:empty) .mes_timer:not(:empty) {
    border-radius: 0 4px 4px 0 !important;
  }
  #chat .mes .mes_text {
    padding-top: calc(var(--mainFontSize) * 0.75) !important;
    padding-bottom: 40px !important; /* 给 swipe 留位，避免短消息时压正文 */
  }
}

/* h3/h4 标题统一背景色/字号(与 drawer 内一致) */
h3.margin0,
h4.margin0,
.popup h3:not(dialog *) {
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, var(--SmartThemeBlurTintColor)) !important;
  font-size: calc(var(--mainFontSize) * 1.15) !important;
  font-weight: 600 !important;
  letter-spacing: 0.03em !important;
  line-height: 2 !important;
}

/* 删除消息模式：勾选框绝对定位，不挤压名字/计数器布局 */
.mes .for_checkbox {
  position: absolute !important;
  top: 6px !important;
  right: 6px !important;
  width: auto !important;
  height: auto !important;
  z-index: 30 !important;
  pointer-events: none !important;
}
.mes input[type="checkbox"].del_checkbox {
  position: absolute !important;
  top: 6px !important;
  right: 6px !important;
  margin: 0 !important;
  z-index: 31 !important;
  pointer-events: auto !important;
}

/* h3/h4 标题：圆角框 + 左竖线 */
.standoutHeader:not(h4),
h3.margin0,
h4.margin0,
.popup h3:not(dialog *) {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

/* standoutHeader 兜底(含h4) */
.standoutHeader {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  background-color: color-mix(in srgb, var(--SmartThemeBorderColor) 60%, var(--SmartThemeBlurTintColor)) !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

/* 抽屉标题保留左竖线 */
.inline-drawer-header {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  background-image: none !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

/* #title_api 加边框+起点对齐 */
#title_api {
  border: 1px solid var(--SmartThemeBorderColor) !important;
  border-left: 3px solid var(--SmartThemeQuoteColor) !important;
  border-radius: 4px !important;
  padding: 4px 8px 4px 12px !important;
  margin-bottom: 4px !important;
}

/* 工具栏整体圆角(PC) */
#top-settings-holder {
  border-radius: 6px;
}
#top-settings-holder > .drawer:first-child,
#top-settings-holder > .drawer:first-child .drawer-toggle {
  border-radius: 6px 0 0 6px;
}
#top-settings-holder > .drawer:last-child,
#top-settings-holder > .drawer:last-child .drawer-toggle {
  border-radius: 0 6px 6px 0;
}

/* 用户人设/角色选中边框：只 Quote 色边,去光晕 */
.avatar-container.selected {
  border-color: var(--SmartThemeQuoteColor) !important;
  box-shadow: none !important;
}
/* 默认人设:圆角外框改主题Quote色 */
.avatar-container.default_persona .avatar {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--SmartThemeQuoteColor) !important;
}
.avatar-container.default_persona .avatar img {
  border-radius: inherit !important;
}
.bogus_folder_select:hover,
.character_select:hover,
.avatar-container:hover {
  background-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, transparent) !important;
}

/* is_fav 收藏头像:圆角外框改主题Quote色 */
.character_select.is_fav .avatar,
.group_select.is_fav .avatar,
.group_member.is_fav .avatar,
.avatar.is_fav {
  outline: none !important;
  box-shadow: 0 0 0 2px var(--SmartThemeQuoteColor) !important;
}
/* 收藏名字用主题 Quote 色 */
.character_select.is_fav .ch_name,
.group_select.is_fav .ch_name,
.group_member.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor) !important;
}
